{
  "findings": [
    {
      "check_id": "CKV_AWS_277",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "Allowing ingress from 0.0.0.0/0 to all ports and protocols (port -1) exposes the resource to the entire internet, increasing the risk of unauthorized access."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Ensure no security groups allow egress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "Allowing egress to 0.0.0.0/0 on all ports and protocols (port -1) can lead to unrestricted data exfiltration or communication with malicious entities."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name   = \"allow-all-lb\"\n  vpc_id = data.aws_vpc.main.id\n\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n\n  egress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}",
  "fix_summary": "Restricted ingress to port 80 (HTTP) and egress to port 443 (HTTPS) with TCP protocol, removing unrestricted access to all ports and protocols."
}
